import meta from "./meta.js";

export const registerGlobal = (runInstructions) => {
    if (!runInstructions || typeof globalThis === "undefined") return;

    globalThis.ks ??= {};
    globalThis.ks.domPrimitive ??= {};

    globalThis.ks.domPrimitive.engine = {
        meta,
        runInstructions
    };
};

export default registerGlobal;